        <div style={{ background: '#0e1526', border: '1px solid #1e293b', padding: '18px', borderRadius: '10px' }}>
          <div style={{ fontSize: '11px', color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Total Tasks</div>
