# Route Handlers for courses (Course)
from fastapi import APIRouter, HTTPException, Depends, Query, status
from pydantic import BaseModel, Field
from typing import List, Optional, Any, Dict
from datetime import datetime

router = APIRouter()

class CourseCreate(BaseModel):
    title: Optional[str] = Field(None, description="Primary label or title")
    name: Optional[str] = Field(None, description="Entity name")
    description: Optional[str] = None
    priority: Optional[str] = "medium"
    status: Optional[str] = "active"
    extra_data: Optional[Dict[str, Any]] = None

class CourseUpdate(BaseModel):
    title: Optional[str] = None
    name: Optional[str] = None
    description: Optional[str] = None
    priority: Optional[str] = None
    status: Optional[str] = None

class CourseResponse(BaseModel):
    id: int
    title: Optional[str] = None
    name: Optional[str] = None
    description: Optional[str] = None
    priority: Optional[str] = "medium"
    status: Optional[str] = "active"
    created_at: Optional[datetime] = None

    class Config:
        from_attributes = True

_courses_db = [
    {"id": 1, "created_at": datetime.utcnow(), "code": "CS-401", "title": "Distributed Systems", "credits": 4, "instructor": "Prof. Turing"},
    {"id": 2, "created_at": datetime.utcnow(), "code": "DS-210", "title": "Applied Machine Learning", "credits": 3, "instructor": "Prof. Hinton"},
    {"id": 3, "created_at": datetime.utcnow(), "code": "SEC-305", "title": "Cloud Security Architecture", "credits": 4, "instructor": "Prof. Diffie"}
]

@router.get("/", response_model=List[Dict[str, Any]])
def list_courses(skip: int = Query(0, ge=0), limit: int = Query(50, le=100)):
    return _courses_db[skip:skip + limit]

@router.post("/", status_code=status.HTTP_201_CREATED)
def create_course(payload: CourseCreate):
    new_id = len(_courses_db) + 1
    new_item = {
        "id": new_id,
        "title": payload.title or payload.name or f"Course {new_id}",
        "name": payload.name or payload.title or f"Course {new_id}",
        "description": payload.description or "",
        "priority": payload.priority or "medium",
        "status": payload.status or "active",
        "created_at": datetime.utcnow()
    }
    if payload.extra_data:
        new_item.update(payload.extra_data)
    _courses_db.append(new_item)
    return new_item

@router.post("/{item_id}/enroll")
def enroll_student(item_id: int):
    return {"course_id": item_id, "status": "enrolled", "student_email": "student@university.edu", "enrolled_at": datetime.utcnow()}

@router.get("/{item_id}")
def get_course(item_id: int):
    for item in _courses_db:
        if item.get("id") == item_id:
            return item
    raise HTTPException(status_code=404, detail="Course record not found")

@router.put("/{item_id}")
def update_course(item_id: int, payload: CourseUpdate):
    for item in _courses_db:
        if item.get("id") == item_id:
            if payload.title is not None: item["title"] = payload.title
            if payload.name is not None: item["name"] = payload.name
            if payload.description is not None: item["description"] = payload.description
            if payload.priority is not None: item["priority"] = payload.priority
            if payload.status is not None: item["status"] = payload.status
            return item
    raise HTTPException(status_code=404, detail="Course record not found")

@router.delete("/{item_id}", status_code=status.HTTP_200_OK)
def delete_course(item_id: int):
    global _courses_db
    initial_len = len(_courses_db)
    _courses_db = [item for item in _courses_db if item.get("id") != item_id]
    if len(_courses_db) == initial_len:
        raise HTTPException(status_code=404, detail="Course record not found")
    return {"deleted": True, "id": item_id, "message": "Course successfully removed"}

